  currency_code text NOT NULL REFERENCES mizan.currencies(code),
  journal_reference text NOT NULL,
  line_reference text NOT NULL,
  posting_date date NOT NULL,
  debit mizan.exact_amount NOT NULL DEFAULT 0 CHECK(debit>=0),
