-- FR-016–019, FR-025, FR-036–037
CREATE TABLE mizan.output_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL,
  entity_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  logical_output_id uuid NOT NULL DEFAULT gen_random_uuid(),
  version integer NOT NULL CHECK (version > 0),
  predecessor_id uuid,
  reopen_reason text,
  output_type text NOT NULL CHECK(output_type IN ('income_statement','financial_position','cash_flows','analysis','reconciliation','executive_pack')),
  period_id uuid NOT NULL,
  currency_code text NOT NULL REFERENCES mizan.currencies(code),
  settings_version_id uuid NOT NULL,
  mapping_version_id uuid,
  preparer_id uuid NOT NULL,
  content_fingerprint text NOT NULL CHECK (content_fingerprint ~ '^[0-9a-f]{64}$'),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','ready_for_review','under_review','rejected','withdrawn','approved_locked')),
  submitted_fingerprint text,
  submitted_at timestamptz,
  locked_at timestamptz,
  CHECK(predecessor_id IS NULL OR length(trim(reopen_reason))>0),
  UNIQUE(tenant_id,entity_id,logical_output_id,version),
  UNIQUE(tenant_id,entity_id,id,currency_code),
  CHECK(status NOT IN ('under_review','approved_locked') OR (submitted_fingerprint=content_fingerprint AND submitted_at IS NOT NULL)),
  CHECK(status<>'approved_locked' OR locked_at IS NOT NULL),
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,entity_id,id)
);

