  similarity_score numeric CHECK(similarity_score BETWEEN 0 AND 1),
  decided_by uuid,
  decision_reason text,
  supervisor_override_by uuid,
  decided_at timestamptz,
  idempotency_key text NOT NULL,
  CHECK(NOT automatic OR (match_kind='one_to_one' AND unique_candidate AND rule_version_id IS NOT NULL AND NOT reference_conflict)),
  CHECK(status IN ('suggested','ambiguous') OR (decision_reason IS NOT NULL AND decided_at IS NOT NULL AND (decided_by IS NOT NULL OR automatic))),
  CHECK(NOT reference_conflict OR status<>'confirmed' OR (supervisor_override_by IS NOT NULL AND length(trim(decision_reason))>0)),
  UNIQUE(tenant_id,entity_id,reconciliation_id,idempotency_key),
  UNIQUE(tenant_id,entity_id,id,bank_account_id,currency_code),
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,entity_id,id)
);

COMMENT ON TABLE mizan.match_groups IS 'FR-027–031 — see docs/DATABASE-SRS.md';

